CREATE TABLE public.booking_enquiries (id UUID NOT NULL DEFAULT gen_random_uuid() PRIMARY KEY, event_type TEXT NOT NULL, event_date TEXT, city TEXT, guests INT, cuisines TEXT[], name TEXT NOT NULL, phone TEXT NOT NULL, status TEXT NOT NULL DEFAULT 'new', created_at TIMESTAMP WITH TIME ZONE NOT NULL DEFAULT now()); GRANT INSERT ON public.booking_enquiries TO anon; GRANT SELECT, INSERT, UPDATE, DELETE ON public.booking_enquiries TO authenticated; GRANT ALL ON public.booking_enquiries TO service_role; ALTER TABLE public.booking_enquiries ENABLE ROW LEVEL SECURITY; CREATE POLICY "Anyone can submit an enquiry" ON public.booking_enquiries FOR INSERT TO anon, authenticated WITH CHECK (true); CREATE POLICY "Admins can view enquiries" ON public.booking_enquiries FOR SELECT TO authenticated USING (public.has_role(auth.uid(), 'admin')); CREATE POLICY "Admins can update enquiries" ON public.booking_enquiries FOR UPDATE TO authenticated USING (public.has_role(auth.uid(), 'admin')); CREATE POLICY "Admins can delete enquiries" ON public.booking_enquiries FOR DELETE TO authenticated USING (public.has_role(auth.uid(), 'admin'));